    public void refreshTrades()
    {
        if (tradeRows == null
                || openPositionRows == null
                || tradeSummary == null
                || tradeMeta == null)
        {
            return;
        }

        tradeRows.removeAll();
        openPositionRows.removeAll();

        W2TradeService.TradeAnalysis analysis =
                tradeService.getAnalysis();

        long realised =
                analysis.getRealisedProfitAfterTax();

        tradeSummary.setText(
                "Realised after tax: "
                        + formatSignedCompact(
                        realised
                )
        );

        tradeSummary.setForeground(
                realised > 0
                        ? GREEN
                        : realised < 0
                        ? RED
                        : MUTED
        );

        int openCount =
                analysis
                        .getOpenPositions()
                        .size();

        tradeMeta.setText(
                "Tax paid: "
                        + formatCompact(
                        analysis.getTaxPaid()
                )
                        + "  •  Open: "
                        + openCount
                        + "  •  Cost: "
                        + formatCompact(
                        analysis.getOpenCost()
                )
        );

        List<W2TradeService.OpenPosition> positions =
                analysis.getOpenPositions();

        if (positions.isEmpty())
        {
            JLabel empty =
                    new JLabel(
                            "No open positions"
                    );

            empty.setForeground(MUTED);
            empty.setFont(BODY);
            empty.setAlignmentX(Component.LEFT_ALIGNMENT);

            openPositionRows.add(empty);
        }
        else
        {
            int shown =
                    Math.min(
                            8,
                            positions.size()
                    );

            for (int i = 0;
                 i < shown;
                 i++)
            {
                addOpenPositionRow(
                        positions.get(i)
                );

                if (i < shown - 1)
                {
                    openPositionRows.add(
                            Box.createVerticalStrut(5)
                    );
                }
            }

            if (positions.size() > shown)
            {
                openPositionRows.add(
                        Box.createVerticalStrut(5)
                );

                JLabel more =
                        new JLabel(
                                "+"
                                        + (positions.size() - shown)
                                        + " more open position"
                                        + (positions.size() - shown == 1
                                        ? ""
                                        : "s")
                        );

                more.setForeground(MUTED);
                more.setFont(SMALL);
                more.setAlignmentX(Component.LEFT_ALIGNMENT);

                openPositionRows.add(more);
            }
        }

        List<W2TradeService.TradeView> views =
                analysis.getTradeViews();

        if (views.isEmpty())
        {
            JLabel empty =
                    new JLabel(
                            "No GE fills recorded yet."
                    );

            empty.setForeground(MUTED);
            empty.setFont(BODY);
            empty.setAlignmentX(Component.LEFT_ALIGNMENT);

            JLabel hint =
                    new JLabel(
                            "Complete a buy or sell in the Grand Exchange."
                    );

            hint.setForeground(MUTED);
            hint.setFont(SMALL);
            hint.setAlignmentX(Component.LEFT_ALIGNMENT);

            tradeRows.add(empty);
            tradeRows.add(Box.createVerticalStrut(4));
            tradeRows.add(hint);
        }
        else
        {
            int shown =
                    Math.min(
                            25,
                            views.size()
                    );

            for (int i = 0;
                 i < shown;
                 i++)
            {
                addTradeRow(
                        views.get(i)
                );

                if (i < shown - 1)
                {
                    tradeRows.add(
                            Box.createVerticalStrut(5)
                    );
                }
            }

            if (views.size() > shown)
            {
                tradeRows.add(
                        Box.createVerticalStrut(5)
                );

                JLabel older =
                        new JLabel(
                                "Showing latest "
                                        + shown
                                        + " fills"
                        );

                older.setForeground(MUTED);
                older.setFont(SMALL);
                older.setAlignmentX(Component.LEFT_ALIGNMENT);
                tradeRows.add(older);
            }
        }

        openPositionRows.revalidate();
        openPositionRows.repaint();

        tradeRows.revalidate();
        tradeRows.repaint();

        revalidate();
        repaint();
    }

