    private JPanel createPage()
    {
        JPanel page = new ViewportWidthPanel();
        page.setLayout(new BoxLayout(page, BoxLayout.Y_AXIS));
        page.setBackground(PANEL_BG);
        page.setBorder(BorderFactory.createEmptyBorder(4, 10, 12, 10));
