package gg.w2;

import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.client.config.ConfigManager;

public class W2WatchlistService
{
    private static final String CONFIG_GROUP = "w2";
    private static final String CONFIG_KEY = "watchlist";

    private final ConfigManager configManager;

    private final Set<Integer> itemIds =
            new LinkedHashSet<>();

    @Inject
    public W2WatchlistService(
            ConfigManager configManager)
    {
        this.configManager = configManager;

        load();
    }

    public boolean contains(
            int itemId)
    {
        return itemIds.contains(
                itemId
        );
    }

    public void add(
            int itemId)
    {
        if (itemIds.add(itemId))
        {
            save();
        }
    }

    public void remove(
            int itemId)
    {
        if (itemIds.remove(itemId))
        {
            save();
        }
    }

    public List<Integer> getAll()
    {
        return new ArrayList<>(
                itemIds
        );
    }

    private void load()
    {
        itemIds.clear();

        String stored =
                configManager.getConfiguration(
                        CONFIG_GROUP,
                        CONFIG_KEY
                );

        if (stored == null
                || stored.trim().isEmpty())
        {
            return;
        }

        String[] parts =
                stored.split(",");

        for (String part : parts)
        {
            try
            {
                int itemId =
                        Integer.parseInt(
                                part.trim()
                        );

                itemIds.add(itemId);
            }
            catch (NumberFormatException ignored)
            {
            }
        }
    }

    private void save()
    {
        StringBuilder value =
                new StringBuilder();

        for (Integer itemId : itemIds)
        {
            if (value.length() > 0)
            {
                value.append(',');
            }

            value.append(itemId);
        }

        configManager.setConfiguration(
                CONFIG_GROUP,
                CONFIG_KEY,
                value.toString()
        );
    }
}

package gg.w2;

import java.math.BigDecimal;
import java.util.Locale;
import javax.inject.Inject;
import net.runelite.client.config.ConfigManager;

public class W2BankService
{
    private static final String CONFIG_GROUP = "w2";
    private static final String CONFIG_KEY = "tradingBank";

    private static final long DEFAULT_BANK =
            100_000_000L;

    private final ConfigManager configManager;

    @Inject
    public W2BankService(
            ConfigManager configManager)
    {
        this.configManager = configManager;
    }

    public long getBank()
    {
        String stored =
                configManager.getConfiguration(
                        CONFIG_GROUP,
                        CONFIG_KEY
                );

        if (stored == null
                || stored.trim().isEmpty())
        {
            return DEFAULT_BANK;
        }

        try
        {
            long bank =
                    Long.parseLong(
                            stored.trim()
                    );

            return bank > 0
                    ? bank
                    : DEFAULT_BANK;
        }
        catch (NumberFormatException ignored)
        {
            return DEFAULT_BANK;
        }
    }

    public void setBank(long bank)
    {
        if (bank < 1)
        {
            return;
        }

        configManager.setConfiguration(
                CONFIG_GROUP,
                CONFIG_KEY,
                Long.toString(bank)
        );
    }

    public long parseAmount(String input)
    {
        if (input == null)
        {
            throw new IllegalArgumentException(
                    "Enter a cash amount"
            );
        }

        String value =
                input.trim()
                        .toLowerCase(Locale.ROOT)
                        .replace(",", "");

        if (value.isEmpty())
        {
            throw new IllegalArgumentException(
                    "Enter a cash amount"
            );
        }

        long multiplier = 1L;

        if (value.endsWith("k"))
        {
            multiplier = 1_000L;
            value =
                    value.substring(
                            0,
                            value.length() - 1
                    );
        }
        else if (value.endsWith("m"))
        {
            multiplier = 1_000_000L;
            value =
                    value.substring(
                            0,
                            value.length() - 1
                    );
        }
        else if (value.endsWith("b"))
        {
            multiplier = 1_000_000_000L;
            value =
                    value.substring(
                            0,
                            value.length() - 1
                    );
        }

        if (!value.matches("\\d+(\\.\\d+)?"))
        {
            throw new IllegalArgumentException(
                    "Use amounts like 50m or 1.2b"
            );
        }

        try
        {
            BigDecimal number =
                    new BigDecimal(value);

            BigDecimal result =
                    number.multiply(
                            BigDecimal.valueOf(
                                    multiplier
                            )
                    );

            if (result.compareTo(
                    BigDecimal.valueOf(Long.MAX_VALUE)) > 0)
            {
                throw new IllegalArgumentException(
                        "Cash amount is too large"
                );
            }

            long amount =
                    result.longValue();

            if (amount < 1)
            {
                throw new IllegalArgumentException(
                        "Enter a cash amount"
                );
            }

            return amount;
        }
        catch (NumberFormatException exception)
        {
            throw new IllegalArgumentException(
                    "Use amounts like 50m or 1.2b"
            );
        }
    }
}

