    private void toggleWatch()
    {
        if (currentItemId < 0)
        {
            return;
        }

        if (watchlistService.contains(currentItemId))
        {
            watchlistService.remove(currentItemId);
        }
        else
        {
            watchlistService.add(currentItemId);
        }

        updateWatchAction();

        if (watchlistChangedListener != null)
        {
            watchlistChangedListener.run();
        }
    }

    private void updateWatchAction()
    {
        if (currentItemId < 0)
        {
            watchAction.setText("☆ Watch");
            watchAction.setToolTipText(null);
            watchAction.setForeground(MUTED);
            return;
        }

        if (watchlistService.contains(currentItemId))
        {
            watchAction.setText("★ Watching");
            watchAction.setToolTipText("Remove from watchlist");
        }
        else
        {
            watchAction.setText("☆ Watch");
            watchAction.setToolTipText("Add to watchlist");
        }

        updateWatchActionColour();
    }

    private void updateWatchActionColour()
    {
        if (currentItemId < 0)
        {
            watchAction.setForeground(MUTED);
            return;
        }

        watchAction.setForeground(
                watchlistService.contains(currentItemId)
                        ? GREEN
                        : GOLD
        );
    }

    private void showData(W2PriceService.W2ItemData data)
    {
        int buy = data.getLow();
        int sell = data.getHigh();

        int tax = calculateTax(sell);
        int profit = sell - buy - tax;

        double roi =
                buy > 0
                        ? (profit * 100.0) / buy
                        : 0.0;

        buyValue.setText(formatGp(buy));
        sellValue.setText(formatGp(sell));

        profitValue.setText(
                (profit >= 0 ? "+" : "")
                        + formatGp(profit)
        );
        profitValue.setForeground(
                profit >= 0
                        ? GREEN
                        : RED
        );

        roiValue.setText(
                String.format(
                        Locale.ROOT,
                        "%.2f%%",
                        roi
                )
        );
        roiValue.setForeground(
                profit >= 0
                        ? GREEN
                        : RED
        );

        taxLabel.setText(
                tax > 0
                        ? "GE tax: " + formatGp(tax)
                        : "No GE tax at this price"
        );

        Integer volume = data.getFiveMinuteVolume();

        if (volume == null)
        {
            tradesValue.setText("Unavailable");
            tradesValue.setForeground(MUTED);
        }
        else
        {
            tradesValue.setText(
                    String.format(
                            Locale.ROOT,
                            "%,d",
                            volume
                    )
            );
            tradesValue.setForeground(Color.WHITE);
        }

        Long newestTimestamp = newestTimestamp(
                data.getHighTime(),
                data.getLowTime()
        );

        if (newestTimestamp == null)
        {
            latestTradeValue.setText("Unavailable");
            latestTradeValue.setForeground(MUTED);
        }
        else
        {
            long age = Math.max(
                    0,
                    Instant.now().getEpochSecond()
                            - newestTimestamp
            );

            latestTradeValue.setText(formatAge(age));
            latestTradeValue.setForeground(Color.WHITE);
        }

        updateActivity(
                volume,
                data.getHighTime(),
                data.getLowTime()
        );

        subtitleLabel.setText("Live OSRS Wiki prices");
        subtitleLabel.setForeground(MUTED);

        revalidate();
        repaint();
    }

    private void updateActivity(
            Integer volume,
            Long highTime,
            Long lowTime)
    {
        if (volume == null)
        {
            activityLabel.setText("No recent volume data");
            activityLabel.setForeground(MUTED);
            return;
        }

        long now = Instant.now().getEpochSecond();
        long oldestAge = 0;

        if (highTime != null)
        {
            oldestAge = Math.max(
                    oldestAge,
                    Math.max(0, now - highTime)
            );
        }

        if (lowTime != null)
        {
            oldestAge = Math.max(
                    oldestAge,
                    Math.max(0, now - lowTime)
            );
        }

        if (highTime != null
                && lowTime != null
                && oldestAge > 900)
        {
            activityLabel.setText("Prices may be stale");
            activityLabel.setForeground(WARNING);
            return;
        }

        if (volume < 10)
        {
            activityLabel.setText("Low recent activity");
            activityLabel.setForeground(WARNING);
        }
        else if (volume < 50)
        {
            activityLabel.setText("Moderate recent activity");
            activityLabel.setForeground(MUTED);
        }
        else
        {
            activityLabel.setText("Active in the last 5 minutes");
            activityLabel.setForeground(GREEN);
        }
    }

    private void showError()
    {
        resetMetrics();

        taxLabel.setText(" ");
        activityLabel.setText("Live market data unavailable");
        activityLabel.setForeground(RED);

        subtitleLabel.setText("Could not load current price data");
        subtitleLabel.setForeground(RED);

        revalidate();
        repaint();
    }

    private void clearDisplay()
    {
        currentItemId = -1;
        currentItemName = null;

        iconLabel.setIcon(null);
        nameLabel.setText("Select an item");
        nameLabel.setToolTipText(null);

        subtitleLabel.setText(" ");
        subtitleLabel.setForeground(MUTED);

        resetMetrics();

        taxLabel.setText(" ");
        activityLabel.setText(" ");

        updateWatchAction();

        selectedState.setVisible(false);
        emptyState.setVisible(true);

        setPreferredSize(new Dimension(0, EMPTY_HEIGHT));
        setMaximumSize(new Dimension(Integer.MAX_VALUE, EMPTY_HEIGHT));

        revalidate();
        repaint();
    }

    private void resetMetrics()
    {
        buyValue.setText("—");
        sellValue.setText("—");
        profitValue.setText("—");
        roiValue.setText("—");
        tradesValue.setText("—");
        latestTradeValue.setText("—");

        buyValue.setForeground(Color.WHITE);
        sellValue.setForeground(Color.WHITE);
        profitValue.setForeground(Color.WHITE);
        roiValue.setForeground(Color.WHITE);
        tradesValue.setForeground(Color.WHITE);
        latestTradeValue.setForeground(Color.WHITE);
    }

    private int calculateTax(int sellPrice)
    {
        long tax = sellPrice / 50L;
        return (int) Math.min(tax, GE_TAX_CAP);
    }

    private Long newestTimestamp(Long highTime, Long lowTime)
    {
        if (highTime == null)
        {
            return lowTime;
        }

        if (lowTime == null)
        {
            return highTime;
        }

        return Math.max(highTime, lowTime);
    }

    private String formatAge(long seconds)
    {
        if (seconds < 60)
        {
            return seconds + " sec ago";
        }

        if (seconds < 3600)
        {
            long minutes = seconds / 60;

            return minutes
                    + (minutes == 1
                    ? " min ago"
                    : " mins ago");
        }

        long hours = seconds / 3600;

        return hours
                + (hours == 1
                ? " hr ago"
                : " hrs ago");
    }

    private String formatGp(long amount)
    {
        return String.format(
                Locale.ROOT,
                "%,d gp",
                amount
        );
    }

    private String shortenName(String name, int maxLength)
    {
        if (name == null || name.length() <= maxLength)
        {
            return name;
        }

        return name.substring(
                0,
                Math.max(1, maxLength - 1)
        ) + "…";
    }
}

package gg.w2;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;

@ConfigGroup("w2")
public interface W2Config extends Config
{
}

package gg.w2;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Consumer;
import javax.inject.Inject;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

public class W2PriceService
{
    private static final String API =
            "https://prices.runescape.wiki/api/v1/osrs/";

    private static final String USER_AGENT =
            "W2 RuneLite Plugin - https://w2.gg";

    private static final int GE_TAX_CAP =
            5_000_000;

    /*
     * Keep the most recent 5-minute market snapshot around briefly so Flips,
     * Lookup and Watch are less likely to show different volume buckets when
     * the Wiki API rolls into a new 5-minute interval between clicks.
     */
    private static final long FIVE_MINUTE_CACHE_MILLIS =
            30_000L;

    private final OkHttpClient httpClient;
    private final Gson gson;

    /*
     * Cached OSRS Wiki item mapping.
     *
     * The mapping contains item IDs, names and GE limits. It changes
     * infrequently, so W2 downloads it once per RuneLite session and reuses
     * it for both Flips and Watch.
     */
    private final Object mappingLock = new Object();
    private Map<Integer, ItemMeta> mappingCache;
    private boolean mappingLoading;

    private final List<Consumer<Map<Integer, ItemMeta>>> mappingSuccessWaiters =
            new ArrayList<>();

    private final List<Consumer<Exception>> mappingErrorWaiters =
            new ArrayList<>();

    private final Object fiveMinuteLock = new Object();
    private FiveMinuteSnapshot fiveMinuteCache;
    private long fiveMinuteCacheLoadedAt;
    private boolean fiveMinuteLoading;

    private final List<Consumer<FiveMinuteSnapshot>> fiveMinuteSuccessWaiters =
            new ArrayList<>();

    private final List<Consumer<Exception>> fiveMinuteErrorWaiters =
            new ArrayList<>();

    @Inject
    public W2PriceService(
            OkHttpClient httpClient,
            Gson gson)
    {
        this.httpClient = httpClient;
        this.gson = gson;
    }

    public void getItemName(
            int itemId,
            Consumer<String> onSuccess,
            Consumer<Exception> onError)
    {
        getMapping(
                mapping ->
                {
                    ItemMeta meta =
                            mapping.get(itemId);

                    if (meta == null)
                    {
                        onError.accept(
                                new IOException(
                                        "Unknown item ID: "
                                                + itemId
                                )
                        );
                        return;
                    }

                    onSuccess.accept(meta.name);
                },
                onError
        );
    }

    private void getMapping(
            Consumer<Map<Integer, ItemMeta>> onSuccess,
            Consumer<Exception> onError)
    {
        Map<Integer, ItemMeta> cached = null;
        boolean startRequest = false;

        synchronized (mappingLock)
        {
            if (mappingCache != null)
            {
                cached = mappingCache;
            }
            else
            {
                mappingSuccessWaiters.add(onSuccess);
                mappingErrorWaiters.add(onError);

                if (!mappingLoading)
                {
                    mappingLoading = true;
                    startRequest = true;
                }
            }
        }

        if (cached != null)
        {
            onSuccess.accept(cached);
            return;
        }

        if (!startRequest)
        {
            return;
        }

        getElement(
                API + "mapping",
                mappingElement ->
                {
                    final Map<Integer, ItemMeta> parsed;

                    try
                    {
                        parsed =
                                parseMapping(
                                        mappingElement.getAsJsonArray()
                                );
                    }
                    catch (Exception exception)
                    {
                        failMappingLoad(exception);
                        return;
                    }

                    final List<Consumer<Map<Integer, ItemMeta>>> successWaiters;

                    synchronized (mappingLock)
                    {
                        mappingCache = parsed;
                        mappingLoading = false;

                        successWaiters =
                                new ArrayList<>(
                                        mappingSuccessWaiters
                                );

                        mappingSuccessWaiters.clear();
                        mappingErrorWaiters.clear();
                    }

                    for (Consumer<Map<Integer, ItemMeta>> waiter
                            : successWaiters)
                    {
                        waiter.accept(parsed);
                    }
                },
                this::failMappingLoad
        );
    }

    private void failMappingLoad(
            Exception exception)
    {
        final List<Consumer<Exception>> errorWaiters;

        synchronized (mappingLock)
        {
            mappingLoading = false;

            errorWaiters =
                    new ArrayList<>(
                            mappingErrorWaiters
                    );

            mappingSuccessWaiters.clear();
            mappingErrorWaiters.clear();
        }

        for (Consumer<Exception> waiter
                : errorWaiters)
        {
            waiter.accept(exception);
        }
    }

    private void getFiveMinuteSnapshot(
            Consumer<FiveMinuteSnapshot> onSuccess,
            Consumer<Exception> onError)
    {
        FiveMinuteSnapshot cached = null;
        boolean startRequest = false;
        long now = System.currentTimeMillis();

        synchronized (fiveMinuteLock)
        {
            if (fiveMinuteCache != null
                    && now - fiveMinuteCacheLoadedAt
                    <= FIVE_MINUTE_CACHE_MILLIS)
            {
                cached = fiveMinuteCache;
            }
            else
            {
                fiveMinuteSuccessWaiters.add(onSuccess);
                fiveMinuteErrorWaiters.add(onError);

                if (!fiveMinuteLoading)
                {
                    fiveMinuteLoading = true;
                    startRequest = true;
                }
            }
        }

        if (cached != null)
        {
            onSuccess.accept(cached);
            return;
        }

        if (!startRequest)
        {
            return;
        }

        getElement(
                API + "5m",
                element ->
                {
                    final FiveMinuteSnapshot snapshot;

                    try
                    {
                        JsonObject root =
                                element.getAsJsonObject();

                        JsonObject data =
                                root.getAsJsonObject("data");

                        if (data == null)
                        {
                            throw new IOException(
                                    "No 5-minute market data"
                            );
                        }

                        snapshot =
                                new FiveMinuteSnapshot(
                                        data,
                                        getNullableLong(
                                                root,
                                                "timestamp"
                                        )
                                );
                    }
                    catch (Exception exception)
                    {
                        failFiveMinuteLoad(exception);
                        return;
                    }

                    final List<Consumer<FiveMinuteSnapshot>> successWaiters;

                    synchronized (fiveMinuteLock)
                    {
                        fiveMinuteCache = snapshot;
                        fiveMinuteCacheLoadedAt =
                                System.currentTimeMillis();
                        fiveMinuteLoading = false;

                        successWaiters =
                                new ArrayList<>(
                                        fiveMinuteSuccessWaiters
                                );

                        fiveMinuteSuccessWaiters.clear();
                        fiveMinuteErrorWaiters.clear();
                    }

                    for (Consumer<FiveMinuteSnapshot> waiter
                            : successWaiters)
                    {
                        waiter.accept(snapshot);
                    }
                },
                this::failFiveMinuteLoad
        );
    }

    private void failFiveMinuteLoad(
            Exception exception)
    {
        final List<Consumer<Exception>> errorWaiters;

        synchronized (fiveMinuteLock)
        {
            fiveMinuteLoading = false;

            errorWaiters =
                    new ArrayList<>(
                            fiveMinuteErrorWaiters
                    );

            fiveMinuteSuccessWaiters.clear();
            fiveMinuteErrorWaiters.clear();
        }

        for (Consumer<Exception> waiter
                : errorWaiters)
        {
            waiter.accept(exception);
        }
    }

    public void getItemData(
            int itemId,
            Consumer<W2ItemData> onSuccess,
            Consumer<Exception> onError)
    {
        getElement(
                API + "latest?id=" + itemId,
                latestElement ->
                {
                    try
                    {
                        JsonObject root =
                                latestElement.getAsJsonObject();

                        JsonObject data =
                                root.getAsJsonObject("data");

                        if (data == null)
                        {
                            throw new IOException(
                                    "No price data"
                            );
                        }

                        JsonObject item =
                                data.getAsJsonObject(
                                        String.valueOf(itemId)
                                );

                        if (item == null)
                        {
                            throw new IOException(
                                    "No item price data"
                            );
                        }

                        Integer high =
                                getNullableInt(
                                        item,
                                        "high"
                                );

                        Integer low =
                                getNullableInt(
                                        item,
                                        "low"
                                );

                        Long highTime =
                                getNullableLong(
                                        item,
                                        "highTime"
                                );

                        Long lowTime =
                                getNullableLong(
                                        item,
                                        "lowTime"
                                );

                        if (high == null
                                || low == null)
                        {
                            throw new IOException(
                                    "Incomplete price data"
                            );
                        }

                        getItemFiveMinuteData(
                                itemId,
                                high,
                                low,
                                highTime,
                                lowTime,
                                onSuccess
                        );
                    }
                    catch (Exception exception)
                    {
                        onError.accept(exception);
                    }
                },
                onError
        );
    }

    private void getItemFiveMinuteData(
            int itemId,
            int high,
            int low,
            Long highTime,
            Long lowTime,
            Consumer<W2ItemData> onSuccess)
    {
        getFiveMinuteSnapshot(
                snapshot ->
                {
                    Integer highVolume = null;
                    Integer lowVolume = null;

                    try
                    {
                        JsonObject item =
                                snapshot.data.getAsJsonObject(
                                        String.valueOf(itemId)
                                );

                        if (item != null)
                        {
                            highVolume =
                                    getNullableInt(
                                            item,
                                            "highPriceVolume"
                                    );

                            lowVolume =
                                    getNullableInt(
                                            item,
                                            "lowPriceVolume"
                                    );
                        }
                    }
                    catch (Exception ignored)
                    {
                    }

                    onSuccess.accept(
                            new W2ItemData(
                                    high,
                                    low,
                                    highTime,
                                    lowTime,
                                    highVolume,
                                    lowVolume,
                                    snapshot.timestamp
                            )
                    );
                },
                exception ->
                        onSuccess.accept(
                                new W2ItemData(
                                        high,
                                        low,
                                        highTime,
                                        lowTime,
                                        null,
                                        null,
                                        null
                                )
                        )
        );
    }

    public void getFlipCandidates(
            Consumer<List<W2FlipCandidate>> onSuccess,
            Consumer<Exception> onError)
    {
        getMapping(
                mapping ->
                        getElement(
                                API + "latest",
                                latestElement ->
                                {
                                    try
                                    {
                                        JsonObject latest =
                                                latestElement
                                                        .getAsJsonObject()
                                                        .getAsJsonObject(
                                                                "data"
                                                        );

                                        getFiveMinuteSnapshot(
                                                snapshot ->
                                                {
                                                    try
                                                    {
                                                        List<W2FlipCandidate> candidates =
                                                                buildCandidates(
                                                                        mapping,
                                                                        latest,
                                                                        snapshot.data,
                                                                        snapshot.timestamp
                                                                );

                                                        onSuccess.accept(
                                                                candidates
                                                        );
                                                    }
                                                    catch (Exception exception)
                                                    {
                                                        onError.accept(
                                                                exception
                                                        );
                                                    }
                                                },
                                                onError
                                        );
                                    }
                                    catch (Exception exception)
                                    {
                                        onError.accept(
                                                exception
                                        );
                                    }
                                },
                                onError
                        ),
                onError
        );
    }

    private Map<Integer, ItemMeta> parseMapping(
            JsonArray array)
    {
        Map<Integer, ItemMeta> result =
                new HashMap<>();

        for (JsonElement element : array)
        {
            JsonObject object =
                    element.getAsJsonObject();

            Integer id =
                    getNullableInt(
                            object,
                            "id"
                    );

            JsonElement nameElement =
                    object.get("name");

            if (id == null
                    || nameElement == null
                    || nameElement.isJsonNull())
            {
                continue;
            }

            Integer limit =
                    getNullableInt(
                            object,
                            "limit"
                    );

            result.put(
                    id,
                    new ItemMeta(
                            id,
                            nameElement.getAsString(),
                            limit == null
                                    ? 0
                                    : limit
                    )
            );
        }

        return result;
    }

    private List<W2FlipCandidate> buildCandidates(
            Map<Integer, ItemMeta> mapping,
            JsonObject latest,
            JsonObject fiveMinute,
            Long fiveMinuteTimestamp)
    {
        List<W2FlipCandidate> result =
                new ArrayList<>();

        if (latest == null)
        {
            return result;
        }

        long now =
                Instant.now()
                        .getEpochSecond();

        for (ItemMeta meta : mapping.values())
        {
            JsonObject price =
                    latest.getAsJsonObject(
                            String.valueOf(meta.id)
                    );

            if (price == null)
            {
                continue;
            }

            Integer high =
                    getNullableInt(
                            price,
                            "high"
                    );

            Integer low =
                    getNullableInt(
                            price,
                            "low"
                    );

            Long highTime =
                    getNullableLong(
                            price,
                            "highTime"
                    );

            Long lowTime =
                    getNullableLong(
                            price,
                            "lowTime"
                    );

            if (high == null
                    || low == null
                    || high <= 0
                    || low <= 0
                    || high <= low)
            {
                continue;
            }

            int tax =
                    calculateTax(high);

            int profit =
                    high
                            - low
                            - tax;

            if (profit <= 0)
            {
                continue;
            }

            double roi =
                    (profit / (double) low)
                            * 100.0;

            if (roi > 25.0)
            {
                continue;
            }

            if (highTime == null
                    || lowTime == null)
            {
                continue;
            }

            long highAge =
                    Math.max(
                            0,
                            now - highTime
                    );

            long lowAge =
                    Math.max(
                            0,
                            now - lowTime
                    );

            long newestAge =
                    Math.min(
                            highAge,
                            lowAge
                    );

            long oldestAge =
                    Math.max(
                            highAge,
                            lowAge
                    );

            /*
             * Keep obviously dead markets out of the list, but do not hide
             * merely slow ones. Slow/thin markets are surfaced with a warning
             * instead of being silently treated as equally trustworthy.
             */
            if (newestAge > 1800
                    || oldestAge > 3600)
            {
                continue;
            }

            Integer highVolume = null;
            Integer lowVolume = null;

            if (fiveMinute != null)
            {
                JsonObject activity =
                        fiveMinute.getAsJsonObject(
                                String.valueOf(meta.id)
                        );

                if (activity != null)
                {
                    highVolume =
                            getNullableInt(
                                    activity,
                                    "highPriceVolume"
                            );

                    lowVolume =
                            getNullableInt(
                                    activity,
                                    "lowPriceVolume"
                            );
                }
            }

            int highVolumeValue =
                    valueOrZero(highVolume);

            int lowVolumeValue =
                    valueOrZero(lowVolume);

            int volume =
                    combinedFiveMinuteVolume(
                            highVolume,
                            lowVolume
                    );

            if (volume < 5)
            {
                continue;
            }

            /*
             * W2 no longer asks for a cash stack. Suggested size is based on
             * the item's GE limit and recent two-sided market activity only.
             * This keeps the shortlist honest instead of forcing different
             * items for arbitrary bank presets.
             */
            long baseQuantity = meta.limit > 0
                    ? meta.limit
                    : Long.MAX_VALUE;

            int smallerSide =
                    weakerSideVolume(
                            highVolume,
                            lowVolume
                    );

            boolean oneSided =
                    isOneSided(
                            highVolume,
                            lowVolume
                    );

            /*
             * A flip needs activity on both sides of the spread.
             *
             * Combined 5-minute volume can look healthy while nearly all of
             * those trades happened on only one side. W2 therefore bases its
             * suggested size on the weaker side and uses only half of that
             * observed activity.
             *
             * This remains a planning aid, not a promise that orders will fill.
             */
            long activityCapacity =
                    Math.max(
                            1L,
                            smallerSide / 2L
                    );

            long quantity =
                    Math.min(
                            baseQuantity,
                            activityCapacity
                    );

            long potential =
                    (long) profit
                            * quantity;

            String marketSignal =
                    marketSignal(
                            highVolume,
                            lowVolume
                    );

            String freshnessSignal =
                    freshnessSignal(
                            highTime,
                            lowTime
                    );

            String liquidityWarning = null;

            if (oneSided)
            {
                if (highVolumeValue < lowVolumeValue)
                {
                    liquidityWarning =
                            "Weak exit-side activity";
                }
                else
                {
                    liquidityWarning =
                            "Weak entry-side activity";
                }
            }
            else if (smallerSide > 0
                    && baseQuantity > (long) smallerSide * 2L)
            {
                liquidityWarning =
                        "Large size vs recent activity";
            }
            else if (smallerSide > 0
                    && baseQuantity > smallerSide)
            {
                liquidityWarning =
                        "This size may take time to fill";
            }
            else if (oldestAge > 900)
            {
                liquidityWarning =
                        "One side of the market is getting stale";
            }

            result.add(
                    new W2FlipCandidate(
                            meta.id,
                            meta.name,
                            meta.limit,
                            low,
                            high,
                            profit,
                            roi,
                            volume,
                            highVolume,
                            lowVolume,
                            highTime,
                            lowTime,
                            fiveMinuteTimestamp,
                            quantity,
                            potential,
                            marketSignal,
                            freshnessSignal,
                            liquidityWarning
                    )
            );
        }

        /*
         * Bank-independent ranking. Prefer real post-tax opportunity backed
         * by two-sided activity, while penalising risky/stale-looking fills.
         */
        result.sort(
                Comparator
                        .<W2FlipCandidate>comparingDouble(
                                W2PriceService::marketOpportunityScore
                        )
                        .reversed()
                        .thenComparing(
                                Comparator.comparingLong(
                                        W2FlipCandidate::getPotentialProfit
                                ).reversed()
                        )
                        .thenComparing(
                                Comparator.comparingInt(
                                        W2FlipCandidate::getWeakerSideVolume
                                ).reversed()
                        )
        );

        if (result.size() > 30)
        {
            return new ArrayList<>(
                    result.subList(
                            0,
                            30
                    )
            );
        }

        return result;
    }

    private static double marketOpportunityScore(
            W2FlipCandidate candidate)
    {
        double profitQuality = Math.log10(
                Math.max(1.0, candidate.getPotentialProfit()) + 1.0
        );

        double activityQuality = Math.log10(
                Math.max(1.0, candidate.getWeakerSideVolume()) + 1.0
        );

        double roiQuality = Math.sqrt(
                Math.min(25.0, Math.max(0.0, candidate.getRoi()))
        );

        double warningPenalty = candidate.hasLiquidityWarning()
                ? 2.0
                : 0.0;

        return (3.0 * profitQuality)
                + (2.0 * activityQuality)
                + roiQuality
                - warningPenalty;
    }

    private static int valueOrZero(
            Integer value)
    {
        return value == null
                ? 0
                : value;
    }

    private static int combinedFiveMinuteVolume(
            Integer highVolume,
            Integer lowVolume)
    {
        return valueOrZero(highVolume)
                + valueOrZero(lowVolume);
    }

    private static int weakerSideVolume(
            Integer highVolume,
            Integer lowVolume)
    {
        return Math.min(
                valueOrZero(highVolume),
                valueOrZero(lowVolume)
        );
    }

    private static boolean isOneSided(
            Integer highVolume,
            Integer lowVolume)
    {
        int smallerSide =
                weakerSideVolume(
                        highVolume,
                        lowVolume
                );

        int largerSide =
                Math.max(
                        valueOrZero(highVolume),
                        valueOrZero(lowVolume)
                );

        return largerSide > 0
                && smallerSide
                < Math.max(
                1,
                largerSide / 5
        );
    }

    private static String marketSignal(
            Integer highVolume,
            Integer lowVolume)
    {
        int high =
                valueOrZero(highVolume);

        int low =
                valueOrZero(lowVolume);

        int total =
                high + low;

        if (total < 10
                || high == 0
                || low == 0)
        {
            return "Low activity";
        }

        if (isOneSided(
                highVolume,
                lowVolume))
        {
            return "One-sided";
        }

        if (total < 50)
        {
            return "Moderate";
        }

        return "Active";
    }

    private static String freshnessSignal(
            Long highTime,
            Long lowTime)
    {
        if (highTime == null
                || lowTime == null)
        {
            return null;
        }

        long now =
                Instant.now()
                        .getEpochSecond();

        long oldestAge =
                Math.max(
                        Math.max(
                                0,
                                now - highTime
                        ),
                        Math.max(
                                0,
                                now - lowTime
                        )
                );

        if (oldestAge <= 300)
        {
            return "Fresh";
        }

        if (oldestAge <= 900)
        {
            return "Recent";
        }

        return "Aging";
    }

    private int calculateTax(
            int sellPrice)
    {
        long tax =
                sellPrice / 50L;

        return (int) Math.min(
                tax,
                GE_TAX_CAP
        );
    }

    private void getElement(
            String url,
            Consumer<JsonElement> onSuccess,
            Consumer<Exception> onError)
    {
        Request request =
                new Request.Builder()
                        .url(url)
                        .header(
                                "User-Agent",
                                USER_AGENT
                        )
                        .build();

        httpClient
                .newCall(request)
                .enqueue(
                        new Callback()
                        {
                            @Override
                            public void onFailure(
                                    Call call,
                                    IOException exception)
                            {
                                onError.accept(
                                        exception
                                );
                            }

                            @Override
                            public void onResponse(
                                    Call call,
                                    Response response)
                                    throws IOException
                            {
                                try (ResponseBody body =
                                             response.body())
                                {
                                    if (!response.isSuccessful()
                                            || body == null)
                                    {
                                        onError.accept(
                                                new IOException(
                                                        "Request failed: "
                                                                + response.code()
                                                )
                                        );

                                        return;
                                    }

                                    JsonElement result =
                                            gson.fromJson(
                                                    body.string(),
                                                    JsonElement.class
                                            );

                                    onSuccess.accept(
                                            result
                                    );
                                }
                                catch (Exception exception)
                                {
                                    onError.accept(
                                            exception
                                    );
                                }
                            }
                        }
                );
    }

    private Integer getNullableInt(
            JsonObject object,
            String name)
    {
        JsonElement value =
                object.get(name);

        if (value == null
                || value.isJsonNull())
        {
            return null;
        }

        return value.getAsInt();
    }

    private Long getNullableLong(
            JsonObject object,
            String name)
    {
        JsonElement value =
                object.get(name);

        if (value == null
                || value.isJsonNull())
        {
            return null;
        }

        return value.getAsLong();
    }

